package com.foodshare.dao;
import java.sql.*; import com.foodshare.database.DBConnection; import com.foodshare.model.DonorRegistrationPOJO; import com.foodshare.service.PasswordUtil;
public class DonorDAO {
 public boolean registerDonor(DonorRegistrationPOJO d){String q="INSERT INTO donors(name,email,mobile,address,password_hash) VALUES(?,?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,d.getName());p.setString(2,d.getEmail().trim().toLowerCase());p.setString(3,d.getMobile());p.setString(4,d.getAddress());p.setString(5,PasswordUtil.hash(d.getPassword()));return p.executeUpdate()==1;}catch(SQLException e){System.err.println("[DonorDAO] Registration failed: "+e.getMessage());return false;}}
 public DonorRegistrationPOJO authenticateDonor(String login,String password){String q="SELECT id,name,email,mobile,address,password_hash FROM donors WHERE lower(email)=lower(?) OR mobile=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,login.trim());p.setString(2,login.trim());try(ResultSet r=p.executeQuery()){if(!r.next()||!PasswordUtil.verify(password,r.getString("password_hash")))return null;DonorRegistrationPOJO d=new DonorRegistrationPOJO();d.setId(r.getInt("id"));d.setName(r.getString("name"));d.setEmail(r.getString("email"));d.setMobile(r.getString("mobile"));d.setAddress(r.getString("address"));return d;}}catch(SQLException e){System.err.println("[DonorDAO] Login failed: "+e.getMessage());return null;}}
 public DonorRegistrationPOJO getDonorByEmail(String email){String q="SELECT id,name,email,mobile,address FROM donors WHERE lower(email)=lower(?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,email);try(ResultSet r=p.executeQuery()){if(!r.next())return null;DonorRegistrationPOJO d=new DonorRegistrationPOJO();d.setId(r.getInt("id"));d.setName(r.getString("name"));d.setEmail(r.getString("email"));d.setMobile(r.getString("mobile"));d.setAddress(r.getString("address"));return d;}}catch(SQLException e){System.err.println("[DonorDAO] Lookup failed: "+e.getMessage());return null;}}
}
